const note = sticky("## CEO Brain — CEO Orchestrator (Agent #0)\nPOST /webhook/ceo-brain/event {type, source, lead_id, task_id, summary, severity, correlation_id, payload, test_mode} — or every hour.\n\nRoutes the event by the routing table (agents/ceo-orchestrator/orchestrator.js), opens exception / review tasks for humans, computes the unresolved-issues list from ceo_tasks + ceo_leads + ceo_agent_runs, rewrites zaphiel/vault/00_CEO_Brain/Management view.md when it changed, emails Ryan on failures (never in test_mode), logs audit + run. Never contacts a customer, never moves money. The inbox to act on it: /webhook/ceo-brain/inbox.\n\nSource of truth: ryan/ceo-brain/workflows/ceo-orchestrator/build.js. Do not hand-edit Code nodes.", [eventHook, hourly, normalize, getTasks], { color: 4 });

export default workflow('ceo-brain-ceo-orchestrator', 'CEO Brain — CEO Orchestrator')
  .add(eventHook)
  .to(normalize)
  .add(hourly)
  .to(normalize)
  .add(normalize)
  .to(getTasks)
  .to(getLeads)
  .to(getRuns)
  .to(orchestrate)
  .to(isEvent
    .onTrue(auditEvent.to(respondEvent).to(hasTasks))
    .onFalse(hasTasks))
  .add(hasTasks
    .onTrue(splitTasks.to(upsertTask).to(getView))
    .onFalse(getView))
  .add(getView)
  .to(prepareView)
  .to(viewChanged
    .onTrue(noteExists
      .onTrue(editView.to(shouldNotify))
      .onFalse(createView.to(shouldNotify)))
    .onFalse(shouldNotify))
  .add(shouldNotify
    .onTrue(emailOwner.to(logRun))
    .onFalse(logRun))
  .add(note);
